package com.northstarbank.core;import java.io.IOException;import org.springframework.context.annotation.*;import org.springframework.security.config.annotation.web.builders.HttpSecurity;import org.springframework.security.web.SecurityFilterChain;import org.springframework.web.filter.OncePerRequestFilter;import jakarta.servlet.*;import jakarta.servlet.http.*;
@Configuration class SecurityConfig{@Bean SecurityFilterChain chain(HttpSecurity h,ScopeToken tokens)throws Exception{h.csrf(c->c.disable()).authorizeHttpRequests(a->a.requestMatchers("/actuator/**","/error").denyAll().anyRequest().authenticated()).addFilterBefore(new TokenFilter(tokens),org.springframework.security.web.authentication.AnonymousAuthenticationFilter.class);return h.build();}static class TokenFilter extends OncePerRequestFilter{private final ScopeToken tokens;TokenFilter(ScopeToken t){tokens=t;}protected void doFilterInternal(HttpServletRequest r,HttpServletResponse p,FilterChain c)throws ServletException,IOException{try{if(r.getRequestURI().startsWith("/core/")){tokens.verify(r.getHeader("Authorization"));var a=new org.springframework.security.authentication.UsernamePasswordAuthenticationToken("decision-token",null,java.util.List.of());org.springframework.security.core.context.SecurityContextHolder.getContext().setAuthentication(a);}c.doFilter(r,p);}catch(RuntimeException e){p.sendError(401);}}}}
